effect.shader:
float hash12(vec2 p){
vec3 p3 = fract(vec3(p.xyx) * 0.1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
mat2 r2(float a){ float s = sin(a), c = cos(a); return mat2(c,-s,s,c); }
bool triMask(vec2 q, bool diag){
float e = 1e-5;
if(!diag){
return (q.x + q.y) <= 1.0 - e;
} else {
return (q.x - q.y) >= e;
}
}
vec2 toPx(vec2 uv){ return uv * inputImg.size; }
vec2 toUv(vec2 px){ vec2 s = inputImg.size; return px / max(s, vec2(1.0)); }
vec4 sampleSafe(vec2 uv){
return texture2DCv(inputImg.texture, clamp(uv, 0.0, 1.0));
}
struct PieceParams { vec2 disp; float rot; vec2 pivotUv; bool diag; float scale; float depth; };
PieceParams getPiece(vec2 cid, float t, float g){
PieceParams P;
vec2 texSize = inputImg.size;
float rnd1 = hash12(cid + float(seed));
float rnd2 = hash12(cid.yx + float(seed)*1.113);
bool diag = mod(cid.x + cid.y, 2.0) < 0.5; P.diag = diag;
vec2 cellOriginPx = (cid + 0.5) * g;
vec2 triPivotOff = (diag ? vec2(0.25, 0.75) : vec2(0.75, 0.25)) - vec2(0.5);
vec2 pivotPx = cellOriginPx + triPivotOff * g * 0.5;
P.pivotUv = toUv(pivotPx);
vec2 fc = forceCenter;
vec2 dir = normalize((toUv(cellOriginPx) - fc));
float angleJitter = (rnd1 - 0.5) * 6.28318530718 * dirRand;
dir = r2(angleJitter) * dir;
float speedMul = 1.0 + (rnd2 - 0.5) * 2.0 * speedRand;
float F = force / max(texSize.x, texSize.y);
vec2 v0 = dir * F * speedMul;
vec2 gy = vec2(0.0, -gravity / max(texSize.y, 1.0));
P.disp = v0 * t + 0.5 * gy * (t*t);
P.rot = radians(spinRate) * t * (0.5 + rnd1);
P.depth = depthAmount * t * (0.25 + rnd2);
P.scale = 1.0 / (1.0 + max(P.depth, 0.0));
return P;
}
vec4 tryCandidate(vec2 cidC, float t, float g, vec2 uvNow, out bool ok){
PieceParams P = getPiece(cidC, t, g);
vec2 uv0 = uvNow - P.disp;
uv0 = (r2(-P.rot) * ((uv0 - P.pivotUv) / max(P.scale, 1e-4))) + P.pivotUv;
vec2 pxy0 = toPx(uv0);
vec2 cid0 = floor(pxy0 / g);
vec2 q0 = fract(pxy0 / g);
bool diag0 = mod(cid0.x + cid0.y, 2.0) < 0.5;
bool inside0 = triMask(q0, diag0);
bool sameCell = all(lessThan(abs(cid0 - cidC), vec2(0.25)));
ok = sameCell && inside0;
vec4 s = ok ? sampleSafe(uv0) : vec4(0.0);
s.a = ok ? P.depth : 1e9;
return s;
}
void main(){
if (acTime < startTime) {
vec4 src0 = texture2DCv(inputImg.texture, acScreenNorm);
gl_FragColor = src0;
return;
}
float t = max(0.0, acTime - startTime);
float g = max(grid, 2.0);
vec2 uvNow = acScreenNorm;
vec2 pxy = toPx(uvNow);
vec2 baseCid = floor(pxy / g);
float texMax = max(inputImg.size.x, inputImg.size.y);
float estDisp = (force / max(texMax, 1.0)) * t + 0.5 * abs(gravity / max(texMax, 1.0)) * t*t;
float cells = estDisp * (texMax / g);
int Rcap = int(clamp(searchMax, 1.0, 12.0));
int R = int(clamp(ceil(cells) + 1.0, 1.0, float(Rcap)));
vec4 col = vec4(0.0);
bool found = false;
float bestDepth = 1e9;
for(int dy=-4; dy<=4 && !found; ++dy){
if(dy < -R || dy > R) continue;
for(int dx=-4; dx<=4 && !found; ++dx){
if(dx < -R || dx > R) continue;
vec2 cidC = baseCid + vec2(float(dx), float(dy));
bool ok; vec4 c = tryCandidate(cidC, t, g, uvNow, ok);
if(ok){
if(c.a < bestDepth){ bestDepth = c.a; col = vec4(c.rgb, 1.0); }
found = true;
}
}
}
gl_FragColor = found ? col : vec4(0.0);
}
